package io.github.marmer.matchergenerator.core.spi;

import io.github.marmer.matchergenerator.core.model.TypeModel;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import java.util.function.Consumer;
import java.util.function.Function;

/**
 * Information about the current generation run that is not part of the model of a type.
 *
 * @param generatorName the name marking generated code as generated by this processor
 * @param generationTime the time of generation
 * @param jspecifyAvailable whether {@code org.jspecify.annotations.NullMarked} resolves at compile
 *     time, which is the condition for emitting JSpecify annotations
 * @param generatedTypes the models of all types generated in this run, whatever configuration asked
 *     for them. A backend learns from them which types get generated code, e.g. to refer to it.
 * @param inheritedMethods the names of the methods of a class on the compile class path, inherited
 *     ones included, by qualified class name; empty for a class that is not there
 * @param errors receives the message of every compiler error a backend reports for the configured
 *     type; the core reports it at the annotation element that configured the type
 * @param kotlinOutputAvailable whether Kotlin sources can be compiled in this run, which is the
 *     case when the annotation processor runs with KAPT. A backend that emits Kotlin only does so
 *     then.
 * @param notes receives the message of every compiler note a backend reports; the core prints it
 *     whatever the verbose option says
 * @param warnings receives the message of every compiler warning a backend reports for the
 *     configured type; the core reports it at the annotation element that configured the type
 * @param verboseNotes receives the message of every compiler note a backend reports that is only
 *     of interest when the processor option {@code matchergenerator.verbose} is set; the core
 *     prints it only then
 */
public record GenerationContext(
        String generatorName,
        LocalDateTime generationTime,
        boolean jspecifyAvailable,
        List<TypeModel> generatedTypes,
        Function<String, Set<String>> inheritedMethods,
        Consumer<String> errors,
        boolean kotlinOutputAvailable,
        Consumer<String> notes,
        Consumer<String> warnings,
        Consumer<String> verboseNotes) {

    public GenerationContext {
        Objects.requireNonNull(generatorName, "generatorName");
        Objects.requireNonNull(generationTime, "generationTime");
        generatedTypes = List.copyOf(generatedTypes);
        Objects.requireNonNull(inheritedMethods, "inheritedMethods");
        Objects.requireNonNull(errors, "errors");
        Objects.requireNonNull(notes, "notes");
        Objects.requireNonNull(warnings, "warnings");
        Objects.requireNonNull(verboseNotes, "verboseNotes");
    }

    /**
     * A context that knows no other generated types and no inherited methods, that offers no Kotlin
     * output, and that cannot report errors, notes or warnings. It drops verbose notes, which only
     * ever are an extra.
     */
    public GenerationContext(
            final String generatorName,
            final LocalDateTime generationTime,
            final boolean jspecifyAvailable) {
        this(
                generatorName,
                generationTime,
                jspecifyAvailable,
                List.of(),
                name -> Set.of(),
                message -> {
                    throw new IllegalStateException("The context cannot report errors: " + message);
                },
                false,
                message -> {
                    throw new IllegalStateException("The context cannot report notes: " + message);
                },
                message -> {
                    throw new IllegalStateException(
                            "The context cannot report warnings: " + message);
                },
                message -> {});
    }

    /**
     * The names of the methods a class has, inherited ones included.
     *
     * @param qualifiedClassName the qualified name of the class
     * @return the method names, empty when the class is not on the compile class path
     */
    public Set<String> inheritedMethodNames(final String qualifiedClassName) {
        return inheritedMethods.apply(qualifiedClassName);
    }

    /**
     * Reports a compiler error for the configured type, which fails the compilation.
     *
     * @param message the error, naming the offending value
     */
    public void reportError(final String message) {
        errors.accept(message);
    }

    /**
     * Reports a compiler note, which does not fail the compilation. A backend that reports the same
     * note for every type has to keep track of that itself.
     *
     * @param message the note
     */
    public void reportNote(final String message) {
        notes.accept(message);
    }

    /**
     * Reports a compiler warning for the configured type, which does not fail the compilation. A
     * backend that reports one per problem names the problem in the message.
     *
     * @param message the warning
     */
    public void reportWarning(final String message) {
        warnings.accept(message);
    }

    /**
     * Reports a compiler note that is printed only when the verbose option is set, such as a
     * decision the backend took that the user might wonder about.
     *
     * @param message the note
     */
    public void reportVerboseNote(final String message) {
        verboseNotes.accept(message);
    }
}
